    if (s > e) {
        return "";
    }
    try {
        return str.substring(s, e);
    } catch (IndexOutOfBoundsException e1) {
        // Fallback: adjust indices to safe values
        s = Math.max(0, Math.min(s, len));
        e = Math.max(s, Math.min(e, len));
        return str.substring(s, e);
    }
}

